def d(x):  # decimal -> text without trailing zeros problem
    s = format(x.normalize(), 'f') if isinstance(x, Dc) else str(x)
    return s
def D_(x): return Dc(str(x))
def fmt(x):
    x = D_(x) if not isinstance(x, Dc) else x
    s = format(x, 'f')
    if '.' in s: s = s.rstrip('0').rstrip('.')
    return s
def W(ans, cand, k=3):
    ans = D_(ans); out = []
    for c in cand:
        c = D_(c)
        if c != ans and c not in out and len(fmt(c)) <= 8: out.append(c)
    step = Dc('0.1')
    i = 1
    while len(out) < k:
        c = ans + step * i * (1 if i % 2 else -1)
        if c != ans and c not in out: out.append(c)
        i += 1
    return [M(fmt(c)) for c in out[:k]]
def lead(s): return s

